from hermes_tools import terminal
code = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('sheets:', wb.sheetnames)
for s in ['Data','Task']:
    ws=wb[s]
    print('\nSHEET', s, 'max_row', ws.max_row, 'max_col', ws.max_column)
    if s=='Data':
        for r in range(18, 40):
            vals=[]
            for c in range(1, min(ws.max_column,15)+1):
                v=ws.cell(r,c).value
                if v is not None:
                    vals.append(f'{get_column_letter(c)}{r}={v!r}')
            if vals:
                print(' ; '.join(vals))
    else:
        for r in list(range(8,33))+list(range(34,51)):
            vals=[]
            for c in range(1, min(ws.max_column,15)+1):
                v=ws.cell(r,c).value
                if v is not None:
                    vals.append(f'{get_column_letter(c)}{r}={v!r}')
            if vals:
                print(' ; '.join(vals))
'''
res=terminal('python3 - <<\'PY\'\n'+code+'\nPY', timeout=120)
print(res['output'])
